    if ((Date.now() - s.created) < Math.max(0, goAt - LEAD)) return 425;   // Too Early: no pre-cue fetch of the answer board
    s._srv = s._srv || {}; s._srv[i] = (s._srv[i] || 0) + 1; if (s._srv[i] > 3) return 404;   // one-shot(+2 retries for RAF/network); can't re-fetch to study
