  // serves every game for free (start -> frame/audio -> grade). Real paid runs do NOT use it; they use the run-bound /api/mini/start +
  // /api/mini/v4frame + /api/crack (all keyed to an open+paid rtv_seeds run). So at public launch (RTV_HIDE_PRACTICE=1) the whole /api/skill/*
  // surface is CLOSED — no free game API anywhere. The password-gated dev twin/admin leaves it open so the team practices via rtv-games-gallery.
  const _practiceClosed = () => process.env.RTV_HIDE_PRACTICE === '1' || process.env.RTV_PUBLIC === '1';   // Jake 2026-09-15: defense-in-depth — the free practice grader is closed on ANY public prod boot, not only when HIDE_PRACTICE is set
  app.post('/api/skill/start', require('express').json(), (req, res) => {
    if (_practiceClosed()) return res.status(403).json({ error: 'practice closed' });
    if (!practiceOk(req)) return res.status(429).json({ error: 'practice rate limit — slow down' });
    try { const out = startSession({ seed: req.body.seed, level: req.body.level, gameKey: req.body.gameKey }); res.json(out); }
    catch (e) { res.status(500).json({ error: 'start', detail: e.message }); }
  });
